def sortTransformedArray(nums, a, b, c):
    def f(x):
        return a * x * x + b * x + c

    n = len(nums)
    res = [0] * n
    left, right = 0, n - 1
    idx = n - 1 if a >= 0 else 0

    while left <= right:
        left_val = f(nums[left])
        right_val = f(nums[right])

        if a >= 0:
            if left_val > right_val:
                res[idx] = left_val
                left += 1
            else:
                res[idx] = right_val
                right -= 1
            idx -= 1
        else:
            if left_val < right_val:
                res[idx] = left_val
                left += 1
            else:
                res[idx] = right_val
                right -= 1
            idx += 1
    return res
